<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Snake</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    background: radial-gradient(circle at top, #1d2b3b, #090d14 65%);
    color: #eef6ff;
    font-family: system-ui, sans-serif;
  }
  .game {
    width: min(92vw, 560px);
    text-align: center;
    padding: 24px;
    border: 1px solid #2d4056;
    border-radius: 20px;
    background: rgba(13, 20, 31, .9);
    box-shadow: 0 18px 60px #0009;
  }
  h1 { margin: 0 0 10px; font-size: 1.5rem; letter-spacing: .12em; }
  .topline {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 0 0 14px;
    color: #a9bdd2;
  }
  #score { color: #8ff7b3; font-size: 1.25rem; font-weight: 800; }
  canvas {
    display: block;
    width: 100%;
    aspect-ratio: 1;
    border: 2px solid #3b5874;
    border-radius: 10px;
    background: #0a1119;
    image-rendering: pixelated;
    box-shadow: inset 0 0 25px #000a;
  }
  .controls { display: flex; gap: 10px; justify-content: center; margin-top: 16px; }
  button {
    border: 1px solid #456783;
    border-radius: 8px;
    padding: 9px 16px;
    color: #eaf5ff;
    background: #1c3043;
    cursor: pointer;
    font: inherit;
    font-weight: 700;
  }
  button:hover { background: #294862; }
  #start { background: #1d6945; border-color: #44b978; }
  #start:hover { background: #278456; }
  .hint { margin: 14px 0 0; color: #8097ae; font-size: .85rem; }
</style>
</head>
<body>
  <main class="game">
    <h1>SNAKE</h1>
    <div class="topline"><span>Score</span><span id="score">0</span></div>
    <canvas id="snake" width="480" height="480" aria-label="Snake game board"></canvas>
    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>
    <p class="hint">Use the arrow keys to steer</p>
  </main>

<script>
(() => {
  const canvas = document.getElementById("snake");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score");
  const W = 20, H = 20, CELL = canvas.width / W;
  const vectors = {
    up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0]
  };

  let body, foodPos, direction, queuedDirection, points, running, timer;

  function same(a, b) { return a[0] === b[0] && a[1] === b[1]; }
  function opposite(a, b) {
    return vectors[a][0] === -vectors[b][0] && vectors[a][1] === -vectors[b][1];
  }
  function freeFood() {
    const open = [];
    for (let y = 0; y < H; y++)
      for (let x = 0; x < W; x++)
        if (!body.some(p => p[0] === x && p[1] === y)) open.push([x, y]);
    return open.length ? open[Math.floor(Math.random() * open.length)] : null;
  }
  function drawCell(x, y, color, inset = 2) {
    ctx.fillStyle = color;
    ctx.fillRect(x * CELL + inset, y * CELL + inset, CELL - inset * 2, CELL - inset * 2);
  }
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = "#142332";
    ctx.lineWidth = 1;
    for (let i = 1; i < W; i++) {
      ctx.beginPath(); ctx.moveTo(i * CELL, 0); ctx.lineTo(i * CELL, canvas.height); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, i * CELL); ctx.lineTo(canvas.width, i * CELL); ctx.stroke();
    }
    if (foodPos) {
      const cx = foodPos[0] * CELL + CELL / 2, cy = foodPos[1] * CELL + CELL / 2;
      ctx.fillStyle = "#ff5c71";
      ctx.beginPath(); ctx.arc(cx, cy, CELL * .32, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#ffd1d8";
      ctx.beginPath(); ctx.arc(cx - 3, cy - 4, CELL * .09, 0, Math.PI * 2); ctx.fill();
    }
    body.forEach((part, i) => drawCell(part[0], part[1], i === 0 ? "#b9ffce" : "#42c978"));
    if (!running) {
      ctx.fillStyle = "rgba(0,0,0,.38)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#ffffff";
      ctx.textAlign = "center";
      ctx.font = "bold 24px system-ui";
      ctx.fillText(points && !foodPos ? "You win!" : (isAlive ? "Ready" : "Game over"), canvas.width / 2, canvas.height / 2);
    }
  }

  let isAlive = true;
  function reset() {
    clearInterval(timer);
    timer = null;
    body = [[7, 10], [6, 10], [5, 10]];
    direction = "right";
    queuedDirection = null;
    points = 0;
    isAlive = true;
    running = false;
    foodPos = freeFood();
    scoreEl.textContent = points;
    draw();
  }
  function tick() {
    if (!isAlive || !foodPos) return;
    if (queuedDirection) {
      direction = queuedDirection;
      queuedDirection = null;
    }
    const [dx, dy] = vectors[direction];
    const head = [body[0][0] + dx, body[0][1] + dy];
    const eating = same(head, foodPos);
    const collisionBody = eating ? body : body.slice(0, -1);
    if (head[0] < 0 || head[0] >= W || head[1] < 0 || head[1] >= H ||
        collisionBody.some(part => same(part, head))) {
      isAlive = false;
      running = false;
      clearInterval(timer);
      timer = null;
      draw();
      return;
    }
    body.unshift(head);
    if (eating) {
      points++;
      scoreEl.textContent = points;
      foodPos = freeFood();
      if (!foodPos) {
        isAlive = false;
        running = false;
        clearInterval(timer);
        timer = null;
      }
    } else {
      body.pop();
    }
    draw();
  }
  function setDir(next) {
    if (!vectors[next] || !isAlive) return;
    const basis = queuedDirection || direction;
    if (!opposite(next, basis)) queuedDirection = next;
  }
  function setFood(x, y) {
    if (Number.isInteger(x) && Number.isInteger(y) && x >= 0 && x < W && y >= 0 && y < H) {
      foodPos = [x, y];
      draw();
    }
  }
  function start() {
    if (!isAlive) reset();
    if (timer) return;
    running = true;
    draw();
    timer = setInterval(tick, 130);
  }
  function pause() {
    clearInterval(timer);
    timer = null;
    running = false;
    draw();
  }

  window.game = {
    w: W, h: H, reset, tick, setDir, setFood,
    snake: () => body.map(p => [p[0], p[1]]),
    food: () => foodPos ? [foodPos[0], foodPos[1]] : null,
    alive: () => isAlive,
    score: () => points
  };

  document.getElementById("start").addEventListener("click", start);
  document.getElementById("pause").addEventListener("click", pause);
  document.getElementById("reset").addEventListener("click", reset);
  addEventListener("keydown", event => {
    const keyMap = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right" };
    if (keyMap[event.key]) {
      event.preventDefault();
      setDir(keyMap[event.key]);
    }
  });
  reset();
})();
</script>
</body>
</html>
